package com.example.takura.communications.controller;
import com.example.takura.communications.application.SesEventService;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/provider-events") public class ProviderWebhookController{private final SesEventService ses;public ProviderWebhookController(SesEventService ses){this.ses=ses;}@PostMapping(value="/ses",consumes="application/json")ResponseEntity<Void> ses(@RequestBody byte[] body){ses.accept(body);return ResponseEntity.noContent().build();}@ExceptionHandler(SecurityException.class)ResponseEntity<Void>forbidden(){return ResponseEntity.status(403).build();}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<Void>bad(){return ResponseEntity.badRequest().build();}}
